// Guía de Azure. Formato de cada dato: [título, explicación sencilla, explicación detallada, ejemplos, cuidado?]
// Prefijos de clave: c_ comando · s_ situación · f_ flag · sin prefijo: concepto de la jerarquía.
const ch = (k, label) => `<button type="button" class="ch" data-k="${k}">${label}</button>`;
const tt = (k, label, clase = "") => `<button type="button" class="tt${clase ? " " + clase : ""}" data-k="${k}">${label}</button>`;

const hero = `
<div class="leyenda"><span><span class="tag tl">Lógica</span> tú la organizas</span><span><span class="tag tf">Física</span> dónde corre</span></div>
<div class="box lo"><div class="hd">${tt("tenant", "Tenant · Microsoft Entra ID")}<span class="tag tl">Lógica</span><span class="t2">la empresa y su identidad</span></div>
<div class="box lo"><div class="hd">${tt("mg", "Management group")}<span class="tag tl">Lógica</span><span class="t2">agrupa suscripciones</span></div>
<div class="box lo"><div class="hd">${tt("sub", "Suscripción")}<span class="tag tl">Lógica</span><span class="t2">facturación, límites y acceso</span></div>
<div class="box lo"><div class="hd">${tt("rg", "Grupo de recursos")}<span class="tag tl">Lógica</span><span class="t2">mismo ciclo de vida</span></div>
<div class="cat mt8"><b>${tt("global", "Servicios globales", "sm")} · no tienen región</b>${ch("frontdoor", "Front Door")}${ch("traffic", "Traffic Manager")}${ch("dns", "Azure DNS")}</div>
<div class="box fi"><div class="hd">${tt("region", "Región · Brazil South")}<span class="tag tf">Física</span><span class="t2">servicios regionales o redundantes en zonas</span></div>
<div class="gr">
<div class="cat"><b>Cómputo</b>${ch("appservice", "App Service")}${ch("functions", "Azure Functions")}${ch("aks", "AKS")}${ch("containerapps", "Container Apps")}${ch("aci", "Container Instances")}</div>
<div class="cat"><b>Red</b>${ch("vnet", "Virtual Network")}${ch("subnet", "Subnet")}${ch("nsg", "NSG")}${ch("lb", "Load Balancer")}${ch("agw", "Application Gateway")}${ch("afw", "Azure Firewall")}${ch("vpn", "VPN Gateway")}${ch("pep", "Private Endpoint")}</div>
<div class="cat"><b>Almacenamiento</b>${ch("storage", "Storage Account")}${ch("blob", "Blob")}${ch("files", "Files")}</div>
<div class="cat"><b>Bases de datos</b>${ch("sql", "Azure SQL")}${ch("psql", "PostgreSQL")}${ch("mysql", "MySQL")}${ch("cosmos", "Cosmos DB")}${ch("redis", "Redis Cache")}</div>
<div class="cat"><b>Integración (middleware)</b>${ch("apim", "API Management")}${ch("servicebus", "Service Bus")}${ch("eventgrid", "Event Grid")}${ch("eventhubs", "Event Hubs")}${ch("logic", "Logic Apps")}</div>
<div class="cat"><b>Seguridad e identidad</b>${ch("kv", "Key Vault")}${ch("mi", "Managed Identity")}${ch("defender", "Defender for Cloud")}</div>
<div class="cat"><b>Monitoreo</b>${ch("monitor", "Azure Monitor")}${ch("log", "Log Analytics")}${ch("appi", "App Insights")}</div>
<div class="cat"><b>DevOps</b>${ch("acr", "Container Registry")}${ch("ado", "Azure DevOps")}</div>
</div>
<div class="hd mt12">${tt("zonas", "Zonas de disponibilidad")}<span class="tag tf">Física</span><span class="t2">recursos zonales: tú eliges la zona</span></div>
<div class="z">
<div class="box fi">${tt("zona", "Zona 1")}<br>${ch("vm", "Virtual Machine")}${ch("disk", "Managed Disk")}${ch("aksnode", "Nodo AKS")}<div class="dc">${tt("dc", "Datacenters", "xs")}</div></div>
<div class="box fi">${tt("zona", "Zona 2")}<br>${ch("vm", "Virtual Machine")}${ch("vmss", "VM Scale Set")}${ch("aksnode", "Nodo AKS")}<div class="dc">${tt("dc", "Datacenters", "xs")}</div></div>
<div class="box fi">${tt("zona", "Zona 3")}<br>${ch("pip", "Public IP")}${ch("sqlrep", "Réplica SQL")}${ch("aksnode", "Nodo AKS")}<div class="dc">${tt("dc", "Datacenters", "xs")}</div></div>
</div>
</div></div></div></div></div>`;

const guia = {
  id: "azure",
  nombre: "Azure",
  titulo: "Guía de Azure",
  descripcion:
    "Jerarquía de Azure de mayor a menor (tenant, suscripción, grupo de recursos, región, zona), servicios por categoría, comandos de Azure CLI, situaciones comunes y flags.",
  resumen: "Jerarquía lógica y física, servicios, Azure CLI y solución de problemas.",
  busqueda: "Buscar (ej. Key Vault, slot, 403, private endpoint, --query)",
  heroTitulo: "Jerarquía de Azure",
  heroResumen: "Conceptos",
  etiquetas: ["En pocas palabras", "En detalle", "Nombre de ejemplo"],
  hero: { tipo: "html", html: hero },
  secciones: [
    {
      titulo: "Comandos más usados (Azure CLI)",
      corto: "Comandos",
      intro: "Todos empiezan con az. Funcionan en Cloud Shell, en tu terminal y en pipelines (tarea AzureCLI de Azure DevOps).",
      mono: true,
      grupos: [
        { nombre: "Sesión y suscripciones", sub: "a qué cuenta le hablo", items: [["c_login", "az login"], ["c_account", "az account"]] },
        { nombre: "Grupos y recursos", sub: "organizar y proteger", items: [["c_group", "az group"], ["c_resource", "az resource / az tag"], ["c_lock", "az lock"]] },
        { nombre: "Cómputo", sub: "VMs, apps y contenedores", items: [["c_vm", "az vm"], ["c_webapp", "az webapp"], ["c_functionapp", "az functionapp"], ["c_aks", "az aks"]] },
        { nombre: "Red", sub: "VNets, NSG y diagnóstico", items: [["c_network", "az network vnet"], ["c_nsg", "az network nsg"], ["c_netwatch", "az network watcher"]] },
        { nombre: "Seguridad e identidad", sub: "secretos y permisos", items: [["c_keyvault", "az keyvault"], ["c_role", "az role assignment"], ["c_identity", "az identity"]] },
        { nombre: "Integración", sub: "middleware", items: [["c_servicebus", "az servicebus"], ["c_apim", "az apim"]] },
        { nombre: "Monitoreo", sub: "qué pasó y cómo va", items: [["c_activity", "az monitor activity-log"], ["c_metrics", "az monitor metrics"], ["c_logs", "az monitor log-analytics"]] },
        { nombre: "IaC, contenedores y ayuda", sub: "desplegar como código", items: [["c_deployment", "az deployment"], ["c_acr", "az acr"], ["c_help", "az find / --help"]] },
      ],
    },
    {
      titulo: "Situaciones comunes y cómo resolverlas",
      corto: "Situaciones",
      grupos: [
        { nombre: "Aplicaciones", sub: "App Service y configuración", items: [["s_appservice", "App Service da 502 / 503"], ["s_kvref", "Referencia a Key Vault no resuelve"], ["s_cert", "Certificado SSL vencido"]] },
        { nombre: "Permisos y gobierno", sub: "quién puede y qué está permitido", items: [["s_authz", "AuthorizationFailed", true], ["s_policy", "RequestDisallowedByPolicy", true], ["s_lock", "ScopeLocked", true]] },
        { nombre: "Red y máquinas", sub: "conectividad", items: [["s_pe", "No conecta por Private Endpoint"], ["s_vm", "VM sin acceso por SSH / RDP"]] },
        { nombre: "Despliegues y capacidad", sub: "crear recursos", items: [["s_deploy", "DeploymentFailed", true], ["s_quota", "QuotaExceeded / SKU no disponible"]] },
        { nombre: "Integración", sub: "mensajería", items: [["s_dlq", "Mensajes en dead-letter (Service Bus)"]] },
      ],
    },
    {
      titulo: "Flags más utilizadas",
      corto: "Flags",
      mono: true,
      grupos: [
        { nombre: "A qué recurso", sub: "identificar el objetivo", items: [["f_g", "-g"], ["f_n", "-n"], ["f_ids", "--ids"], ["f_sub", "--subscription"], ["f_l", "-l"]] },
        { nombre: "Salida", sub: "formato y filtros", items: [["f_o", "-o"], ["f_query", "--query"]] },
        { nombre: "Ejecución", sub: "confirmar, esperar, depurar", items: [["f_yes", "--yes"], ["f_nowait", "--no-wait"], ["f_debug", "--debug / --verbose"], ["f_only", "--only-show-errors"]] },
        { nombre: "Comodidad", sub: "menos escritura", items: [["f_defaults", "az config set defaults"], ["f_help", "-h / --help"]] },
      ],
    },
  ],
  datos: {
    tenant: ["Tenant (Microsoft Entra ID)", "Es la empresa dentro de Azure: su directorio de usuarios y permisos.", "Es una instancia de Microsoft Entra ID (antes Azure AD). Contiene usuarios, grupos, aplicaciones y las reglas de inicio de sesión (MFA, acceso condicional). Una empresa normalmente tiene un solo tenant y de él cuelgan todas sus suscripciones. Cuando entras al portal, inicias sesión contra un tenant.", "contoso.onmicrosoft.com"],
    mg: ["Management group", "Carpetas para agrupar suscripciones y darles reglas en bloque.", "Organizan las suscripciones en un árbol de hasta 6 niveles bajo la raíz. Lo que asignas en un management group (permisos RBAC y Azure Policy) lo heredan todas las suscripciones de abajo. Ejemplo típico: mg-plataforma para red e identidad compartidas y mg-cargas para las aplicaciones, con una política como 'solo se permite desplegar en Brazil South'.", "mg-cargas"],
    sub: ["Suscripción", "La cuenta donde se crean y se cobran los recursos.", "Es la frontera de facturación (cada una tiene su costo), de cuotas (límites como número de vCPU) y de acceso. Pertenece a un solo tenant. Es común separar por ambiente (prod, dev) para que un error en pruebas no afecte producción y para ver cuánto cuesta cada uno. Una misma suscripción puede tener recursos en cualquier región del mundo.", "sub-pagos-prod"],
    rg: ["Grupo de recursos", "Una carpeta para recursos que se crean, se cambian y se borran juntos.", "Todo recurso vive en exactamente un grupo. Se agrupan por ciclo de vida: si borras el grupo, se borra todo lo que contiene. Los permisos, políticas y locks se pueden aplicar a nivel de grupo. El grupo tiene una región, pero solo para guardar sus metadatos: puede contener recursos de otras regiones. Los recursos se pueden mover entre grupos.", "rg-pagos-prod-brs-001"],
    global: ["Servicios globales", "Servicios que no viven en una región: funcionan desde todo el mundo.", "Algunos servicios se despliegan de forma global: Front Door y Traffic Manager reparten tráfico entre regiones, y Azure DNS responde desde servidores en todo el mundo. Igual pertenecen a un grupo de recursos, pero la caída de una región no los afecta. Por eso son la pieza clave cuando una aplicación corre en varias regiones.", "afd-pagos-prod"],
    region: ["Región", "Una zona geográfica (por ejemplo São Paulo) donde Azure tiene centros de datos.", "Es un conjunto de datacenters cercanos unidos por una red de muy baja latencia. Al crear casi cualquier recurso eliges la región, y eso define la latencia hacia tus usuarios, el precio, los servicios disponibles y dónde quedan legalmente los datos. Muchas regiones tienen una región pareada para recuperación ante desastres (Brazil South se parea con South Central US). Para Colombia, la más cercana es Brazil South.", "brazilsouth"],
    zonas: ["Zonas de disponibilidad", "Partes separadas de una región para que una falla no tumbe todo.", "Las regiones con zonas tienen al menos 3. Cada zona tiene su propia energía, refrigeración y red, así que un corte o un incendio en una no afecta a las otras. Se usan de dos formas: recursos zonales (tú fijas la VM en la zona 1) y recursos redundantes en zonas (Azure replica el servicio en las 3 por ti). Repartir en zonas da alta disponibilidad dentro de la región.", "zona 1, 2 y 3"],
    zona: ["Zona de disponibilidad", "Una de las 3 ubicaciones independientes dentro de la región.", "Cada zona es uno o más datacenters con energía, refrigeración y red propias. Para que la caída de una zona no tumbe la aplicación, repartes instancias en zonas distintas. Detalle útil: los números de zona son lógicos por suscripción, así que la 'zona 1' de tu suscripción puede ser físicamente otra que la 'zona 1' de otra suscripción.", "--zone 1"],
    dc: ["Centro de datos (datacenter)", "El edificio físico con los servidores. Lo maneja Microsoft.", "Cada zona está formada por uno o más datacenters. Nunca eliges ni ves un datacenter específico: Microsoft decide dónde cae cada recurso dentro de la zona. Dentro del datacenter existen los fault domains (racks con energía y red propias); un Availability Set reparte tus VMs en racks distintos para resistir la falla de uno.", "(lo administra Microsoft)"],
    frontdoor: ["Azure Front Door", "Puerta de entrada global a tus aplicaciones web.", "Recibe el tráfico en ubicaciones de Microsoft cercanas al usuario, lo acelera con caché (CDN), lo filtra con WAF y lo envía a la región sana más cercana. Si una región cae, redirige automáticamente a otra.", "afd-pagos-prod"],
    traffic: ["Traffic Manager", "Reparte usuarios entre regiones usando DNS.", "Responde las consultas DNS con la dirección de la región que convenga según la regla (prioridad, rendimiento, geografía). El tráfico no pasa por él: solo indica a dónde ir, por eso funciona con cualquier protocolo.", "traf-pagos-prod"],
    dns: ["Azure DNS", "Guarda los registros DNS de tus dominios.", "Hospeda zonas DNS públicas (contoso.com apunta a una IP) en la red global de Microsoft. También existe Azure Private DNS para resolver nombres dentro de tus VNets, clave para que funcionen los private endpoints.", "contoso.com"],
    appservice: ["App Service", "Publica una web o una API sin administrar servidores.", "Es PaaS: subes el código o un contenedor y Azure maneja sistema operativo, parches y balanceo. Corre sobre un App Service Plan, que define el tamaño y el número de instancias; varias apps pueden compartir plan. Tiene deployment slots (desde el tier Standard) para desplegar en staging y hacer swap a producción sin downtime, autoescalado y referencias a Key Vault en la configuración.", "app-pagos-api-prod-brs"],
    functions: ["Azure Functions", "Código pequeño que se ejecuta cuando pasa algo.", "Es serverless: escribes una función que se dispara por un evento (petición HTTP, mensaje en Service Bus, archivo nuevo en Blob, un horario). En el plan de consumo pagas solo por ejecución y escala solo. Ideal para tareas cortas e integraciones.", "func-pagos-prod-brs"],
    aks: ["Azure Kubernetes Service (AKS)", "Kubernetes administrado para correr contenedores.", "Azure administra el control plane de Kubernetes y tú administras los node pools (las VMs donde corren los pods) y los despliegues. Los nodos se pueden repartir en las 3 zonas. Se integra con Container Registry, Entra ID y Azure Monitor.", "aks-pagos-prod-brs"],
    containerapps: ["Azure Container Apps", "Contenedores sin tener que administrar Kubernetes.", "Corre microservicios en contenedores con Kubernetes por debajo, pero sin que veas ni administres el clúster. Escala automáticamente (incluso a cero) según peticiones o eventos. Es el punto medio entre App Service y AKS.", "ca-pagos-prod-brs"],
    aci: ["Azure Container Instances", "Un contenedor suelto que arranca en segundos.", "Ejecuta uno o pocos contenedores sin orquestador ni VMs, y se paga por segundo. Útil para tareas puntuales, procesos batch o agentes de build temporales.", "ci-batch-prod-brs"],
    vnet: ["Virtual Network (VNet)", "Tu red privada dentro de Azure.", "Define un rango de IPs privadas (por ejemplo 10.10.0.0/16) en una región y abarca todas sus zonas. Los recursos dentro se comunican en privado. Se conecta con otras VNets (peering), con tu red local (VPN o ExpressRoute) y se divide en subredes.", "vnet-prod-brs-001"],
    subnet: ["Subnet", "Un pedazo de la red para agrupar recursos.", "Divide la VNet en segmentos (por ejemplo 10.10.1.0/24 para apps y 10.10.2.0/24 para datos). A cada subred se le asocian un NSG y tablas de rutas. Una subred también abarca las 3 zonas. Algunos servicios exigen subred dedicada (Application Gateway, VPN Gateway).", "snet-app-prod-brs"],
    nsg: ["Network Security Group (NSG)", "Reglas de firewall: qué tráfico entra y qué sale.", "Lista de reglas con prioridad (origen, destino, puerto, protocolo, permitir o denegar). Se asocia a una subred o a la tarjeta de red de una VM. Trae reglas por defecto que permiten el tráfico dentro de la VNet y bloquean lo que llega de internet.", "nsg-snet-app-prod"],
    lb: ["Azure Load Balancer", "Reparte el tráfico de red entre varios servidores.", "Balanceador de capa 4: trabaja con IP y puerto (TCP/UDP) sin mirar el contenido HTTP. Puede ser público o interno. Usa health probes para enviar tráfico solo a instancias sanas. El SKU Standard es redundante en zonas.", "lbi-pagos-prod-brs"],
    agw: ["Application Gateway", "Balanceador para tráfico web, con protección.", "Balanceador de capa 7: entiende HTTP, así que enruta por URL o por host, termina SSL y puede incluir WAF (Web Application Firewall) contra ataques como inyección SQL. Necesita subred dedicada. La versión v2 es redundante en zonas y escala sola.", "agw-pagos-prod-brs"],
    afw: ["Azure Firewall", "Firewall central administrado por Azure.", "Firewall con estado que filtra el tráfico entre redes y hacia internet con reglas de red, de aplicación (por FQDN) e inteligencia de amenazas. Normalmente se ubica en la VNet central (hub) de una topología hub-and-spoke, y todo el tráfico pasa por él.", "afw-hub-prod-brs"],
    vpn: ["VPN Gateway", "Túnel seguro entre tu oficina y Azure.", "Crea túneles IPsec cifrados por internet entre tu red local (o los equipos de los usuarios) y la VNet. Para conexiones privadas dedicadas, sin pasar por internet, se usa ExpressRoute. Requiere una subred llamada GatewaySubnet.", "vpng-hub-prod-brs"],
    pep: ["Private Endpoint", "Le da una IP privada a un servicio como SQL o Key Vault.", "Crea una tarjeta de red con IP privada en tu subred, conectada a un servicio PaaS. Así el tráfico hacia ese servicio no sale a internet y puedes deshabilitar su acceso público. Requiere una Private DNS Zone para que el nombre del servicio resuelva a la IP privada.", "pep-sql-pagos-prod"],
    storage: ["Storage Account", "Almacenamiento para archivos, blobs, colas y tablas.", "Agrupa varios servicios: Blob (objetos), Files (carpetas compartidas), Queue (colas simples) y Table (clave-valor). Define la redundancia: LRS (3 copias en un datacenter), ZRS (en las 3 zonas) o GRS (copia en la región pareada). El nombre es único global, en minúsculas, sin guiones, de 3 a 24 caracteres.", "stpagosprodbrs001"],
    blob: ["Blob Storage", "Guarda archivos de cualquier tipo (objetos).", "Almacena objetos dentro de contenedores: imágenes, PDF, backups, logs. Tiene niveles de acceso (Hot, Cool, Cold, Archive) para pagar menos por lo que casi no se consulta, y políticas de ciclo de vida que los mueven automáticamente.", "contenedor: facturas"],
    files: ["Azure Files", "Carpetas compartidas en la nube.", "Comparte archivos por SMB o NFS, como una unidad de red. Se monta desde VMs, desde equipos locales o desde contenedores. Útil para migrar aplicaciones que esperan un disco compartido.", "share: compartida"],
    sql: ["Azure SQL Database", "Base de datos SQL Server administrada por Azure.", "Es PaaS: Azure se encarga de parches, backups automáticos y alta disponibilidad. Se compone de un servidor lógico (seguridad, firewall, red) y las bases de datos. Puede ser redundante en zonas y tener réplicas en otra región (failover groups). Se protege con Private Endpoint y autenticación con Entra ID.", "sql-pagos-prod-brs / sqldb-pagos"],
    psql: ["Azure Database for PostgreSQL", "PostgreSQL administrado.", "Servidor flexible: Azure maneja backups, parches y alta disponibilidad (con réplica en otra zona si la activas). Tú manejas la base, los usuarios y los parámetros.", "psql-pagos-prod-brs"],
    mysql: ["Azure Database for MySQL", "MySQL administrado.", "Servidor flexible con el mismo modelo que PostgreSQL: backups automáticos, alta disponibilidad entre zonas opcional e integración con VNet.", "mysql-pagos-prod-brs"],
    cosmos: ["Azure Cosmos DB", "Base de datos NoSQL rápida y distribuida.", "Ofrece varias APIs (NoSQL nativa, MongoDB, Cassandra, Gremlin, Table). Replica los datos en las regiones que elijas con latencia muy baja y niveles de consistencia configurables. Se cobra por throughput (RU/s) o en modo serverless.", "cosmos-pagos-prod"],
    redis: ["Azure Cache for Redis", "Memoria rápida para no consultar la base de datos cada vez.", "Caché en memoria basado en Redis. Guarda datos frecuentes (sesiones, resultados de consultas) para responder en milisegundos y quitarle carga a la base de datos.", "redis-pagos-prod-brs"],
    apim: ["API Management", "La puerta de entrada y el control de tus APIs.", "Es un gateway delante de tus APIs: los clientes llaman a APIM y APIM llama al backend. Aplica políticas (validar tokens JWT, límites de peticiones, transformar datos, CORS), maneja productos y suscripciones con llaves, versiones y un portal para desarrolladores. Registra métricas en Application Insights. El tier Premium permite multi-región e integración completa con VNet.", "apim-pagos-prod-brs"],
    servicebus: ["Azure Service Bus", "Mensajería confiable entre aplicaciones.", "Un namespace contiene colas (un emisor, un receptor) y topics con suscripciones (un emisor, muchos receptores). Garantiza que el mensaje no se pierda: el receptor lo bloquea (peek-lock), lo procesa y lo confirma. Si falla varias veces (10 por defecto) va a la dead-letter queue para revisarlo. Los topics requieren tier Standard o Premium.", "sbns-pagos-prod-brs"],
    eventgrid: ["Azure Event Grid", "Avisa a otros servicios cuando algo pasa.", "Enrutador de eventos con modelo push: un origen (por ejemplo 'se subió un blob') publica un evento y Event Grid lo entrega a los suscriptores (Functions, Logic Apps, webhooks). Es liviano y está pensado para reaccionar, no para mensajes de negocio que no se pueden perder.", "evgt-pagos-prod"],
    eventhubs: ["Azure Event Hubs", "Recibe millones de eventos por segundo.", "Plataforma de ingesta de streaming: telemetría, logs, clics. Los eventos se guardan en particiones durante un tiempo y varios consumidores los leen a su ritmo. Es compatible con el protocolo de Kafka.", "evhns-telemetria-prod"],
    logic: ["Azure Logic Apps", "Automatiza integraciones con bloques, casi sin código.", "Diseñas un flujo con un disparador (horario, correo, petición HTTP) y acciones de cientos de conectores (SQL, SAP, Outlook, SharePoint). Consumption cobra por ejecución; Standard corre en un plan dedicado y soporta VNet. Se monitorea con el historial de ejecuciones.", "logic-conciliacion-prod"],
    kv: ["Azure Key Vault", "Caja fuerte para contraseñas, llaves y certificados.", "Guarda secretos, llaves de cifrado y certificados (con renovación automática). El acceso se controla con RBAC y queda registrado para auditoría. Soft delete y purge protection evitan borrados accidentales. Las apps lo leen con Managed Identity, sin credenciales en el código. Nombre único global de 3 a 24 caracteres.", "kv-pagos-prod-brs"],
    mi: ["Managed Identity", "Una identidad para que la app entre a otros servicios sin contraseña.", "Azure crea y rota la credencial automáticamente. Le das roles RBAC (por ejemplo leer secretos de Key Vault) y la app se autentica sola. System-assigned: nace y muere con el recurso. User-assigned: es un recurso independiente que se puede compartir entre varios.", "id-app-pagos-prod"],
    defender: ["Microsoft Defender for Cloud", "Revisa qué tan segura está tu nube y alerta amenazas.", "Evalúa la configuración contra buenas prácticas (Secure Score), recomienda correcciones y, con los planes pagos, detecta amenazas en VMs, contenedores, bases de datos y Storage. Se activa por suscripción.", "(se activa por suscripción)"],
    monitor: ["Azure Monitor", "El sistema central de métricas y alertas de Azure.", "Recolecta métricas de todos los recursos (CPU, peticiones, errores) y permite crear alertas que disparan action groups (correo, Teams, SMS, webhook, runbook). Log Analytics y Application Insights son parte de esta misma plataforma.", "(métricas y alertas)"],
    log: ["Log Analytics", "Donde se guardan y consultan los logs.", "Un workspace centraliza los logs de recursos, VMs, AKS y seguridad. Se consulta con KQL (Kusto Query Language) para investigar incidentes o crear alertas sobre logs. Define la retención y el costo por GB ingerido.", "log-prod-brs-001"],
    appi: ["Application Insights", "Ve cómo se comporta tu aplicación por dentro.", "Es APM: registra peticiones, tiempos de respuesta, excepciones y dependencias (llamadas a SQL o a otras APIs). Tiene mapa de aplicación, pruebas de disponibilidad y trazas distribuidas. Guarda sus datos en un workspace de Log Analytics.", "appi-pagos-prod-brs"],
    acr: ["Azure Container Registry", "Bodega privada de imágenes de contenedores.", "Registro privado compatible con Docker y OCI. AKS, App Service y Container Apps descargan las imágenes desde aquí. Puede escanear vulnerabilidades (con Defender) y replicarse en varias regiones (tier Premium). El nombre va sin guiones.", "acrpagosprod"],
    ado: ["Azure DevOps", "Plataforma para código, pipelines y gestión del trabajo.", "Es un servicio SaaS aparte del portal de Azure: Repos (Git), Pipelines (CI/CD), Boards (trabajo ágil), Artifacts (paquetes) y Test Plans. Se conecta a tus suscripciones mediante service connections para desplegar.", "dev.azure.com/contoso"],
    vm: ["Virtual Machine", "Un servidor completo en la nube.", "Es IaaS: eliges tamaño (vCPU, RAM), sistema operativo e imagen, y tú administras parches, software y seguridad del sistema operativo. Es un recurso zonal: la fijas a una zona, y para alta disponibilidad pones varias VMs en zonas distintas detrás de un balanceador.", "vm-pagos-prod-brs-01"],
    disk: ["Managed Disk", "El disco duro de una VM.", "Disco administrado (Standard HDD, Standard SSD, Premium SSD, Ultra). Vive en la misma zona que su VM. Se respalda con snapshots o Azure Backup y se puede cifrar con llaves propias guardadas en Key Vault.", "disk-vm-pagos-01"],
    aksnode: ["Nodo de AKS", "Una de las máquinas donde corren los contenedores de AKS.", "Los node pools de AKS son VM Scale Sets por debajo. Si los creas en las zonas 1, 2 y 3, Kubernetes reparte los nodos y puedes distribuir los pods para que la caída de una zona no tumbe la aplicación.", "aks-nodepool1-vmss"],
    vmss: ["Virtual Machine Scale Set", "Un grupo de VMs iguales que crece y decrece solo.", "Todas las instancias salen de la misma imagen y configuración. Escala por métricas (por ejemplo CPU mayor a 70 %) o por horario, y puede repartir instancias entre zonas. AKS lo usa por debajo para sus nodos.", "vmss-pagos-prod-brs"],
    pip: ["Public IP", "Una dirección IP pública para exponer algo a internet.", "Puede ser zonal (fijada a una zona) o redundante en zonas. El SKU Standard es seguro por defecto: bloquea el tráfico entrante hasta que un NSG lo permita. Se asocia a VMs, balanceadores o gateways.", "pip-vm-pagos-03"],
    sqlrep: ["Réplica de Azure SQL", "Una copia automática de la base de datos en otra zona.", "Al activar la redundancia en zonas en Azure SQL, Azure mantiene réplicas sincrónicas en otras zonas. Si la zona principal falla, conmuta automáticamente, sin perder datos y sin cambiar nada en la aplicación.", "(automática)"],

    c_login: ["az login", "Inicia sesión en Azure desde la terminal.", "Sin opciones abre el navegador para autenticarte con tu cuenta de Entra ID (con MFA). Si no hay navegador (servidor o SSH), usa --use-device-code. Las automatizaciones no usan tu usuario: un pipeline entra con un service principal o, mejor, con una managed identity o federación de identidad (OIDC), sin contraseñas guardadas. En Azure DevOps, la tarea AzureCLI hace el login con la service connection.", ["az login", "az login --use-device-code", "az login --tenant contoso.onmicrosoft.com", "az login --identity            # desde una VM o agente con managed identity", "az logout"]],
    c_account: ["az account", "Ver y cambiar la suscripción activa.", "Todos los comandos se ejecutan contra la suscripción activa. Un error clásico es crear o borrar algo en la suscripción equivocada: revisa con az account show antes de cualquier cambio importante. set cambia la suscripción por nombre o ID.", ["az account show -o table", "az account list -o table", "az account set --subscription \"sub-pagos-prod\"", "az account list-locations -o table"]],
    c_group: ["az group", "Crear, listar y borrar grupos de recursos.", "El grupo de recursos es el contenedor básico: casi todos los comandos piden -g. Borrar un grupo borra todos los recursos que contiene, por eso pide confirmación (y conviene protegerlo con un lock).", ["az group create -n rg-pagos-dev-brs-001 -l brazilsouth --tags env=dev app=pagos", "az group list -o table", "az group show -n rg-pagos-prod-brs-001", "az group delete -n rg-pagos-dev-brs-001 --yes --no-wait"], "az group delete borra todo lo que hay dentro del grupo y no se puede deshacer."],
    c_resource: ["az resource / az tag", "Buscar recursos de cualquier tipo y manejar sus etiquetas.", "az resource trabaja con cualquier tipo de recurso de forma genérica: listar todo lo de un grupo, buscar por etiqueta o ver un recurso por su ID completo. az tag agrega o cambia etiquetas (costos, dueño, ambiente) sin borrar las existentes si usas --operation merge.", ["az resource list -g rg-pagos-prod-brs-001 -o table", "az resource list --tag env=prod --query \"[].{nombre:name, tipo:type}\" -o table", "az resource show --ids <id-del-recurso>", "az tag update --resource-id <id> --operation merge --tags owner=juan cost-center=ti"]],
    c_lock: ["az lock", "Protege recursos contra borrados o cambios accidentales.", "Un lock CanNotDelete permite modificar pero no borrar; ReadOnly impide cualquier cambio (y puede romper operaciones que parecen de lectura, como listar las llaves de un Storage Account). Se aplican a suscripción, grupo o recurso y se heredan. Incluso un Owner debe quitar el lock antes de borrar.", ["az lock create -n no-borrar --lock-type CanNotDelete -g rg-pagos-prod-brs-001", "az lock list -g rg-pagos-prod-brs-001 -o table", "az lock delete -n no-borrar -g rg-pagos-prod-brs-001"]],
    c_vm: ["az vm", "Crear y operar máquinas virtuales.", "Detalle clave: stop apaga el sistema operativo, pero Azure sigue cobrando el cómputo porque reserva el hardware; deallocate libera el hardware y deja de cobrarlo (la IP pública dinámica puede cambiar). run-command ejecuta un script dentro de la VM sin entrar por SSH o RDP, muy útil cuando la red falla. -d en list agrega estado e IPs.", ["az vm list -d -o table                  # con estado e IPs", "az vm start -g <rg> -n vm-pagos-prod-brs-01", "az vm deallocate -g <rg> -n vm-pagos-prod-brs-01   # deja de cobrar cómputo", "az vm run-command invoke -g <rg> -n <vm> --command-id RunShellScript --scripts \"df -h\"", "az vm get-instance-view -g <rg> -n <vm> --query instanceView.statuses"]],
    c_webapp: ["az webapp", "Administrar App Service: logs, configuración, slots y despliegues.", "Los comandos más usados en operación: ver logs en vivo (primero hay que habilitar el logging), reiniciar, cambiar App Settings (llegan a la app como variables de entorno y la reinician), hacer swap de slots (despliegue y rollback sin downtime) y desplegar un paquete zip.", ["az webapp list -o table", "az webapp log config -g <rg> -n <app> --application-logging filesystem", "az webapp log tail -g <rg> -n <app>", "az webapp config appsettings set -g <rg> -n <app> --settings LOG_LEVEL=info", "az webapp deployment slot swap -g <rg> -n <app> --slot staging --target-slot production", "az webapp deploy -g <rg> -n <app> --src-path app.zip --type zip", "az webapp restart -g <rg> -n <app>"]],
    c_functionapp: ["az functionapp", "Administrar Function Apps.", "Comparte casi todo con az webapp: configuración, reinicio, slots y despliegue zip. Para publicar desde el código local se usa Azure Functions Core Tools (func).", ["az functionapp list -o table", "az functionapp config appsettings set -g <rg> -n func-pagos-prod-brs --settings \"QUEUE_NAME=ordenes\"", "az functionapp restart -g <rg> -n func-pagos-prod-brs", "func azure functionapp publish func-pagos-prod-brs"]],
    c_aks: ["az aks", "Administrar clústeres AKS (lo que está por fuera de Kubernetes).", "Con az aks manejas la infraestructura del clúster: credenciales para kubectl, versiones y actualizaciones, node pools, la integración con ACR y encender o apagar el clúster (útil en dev para ahorrar). Lo de adentro (pods, deployments) se maneja con kubectl.", ["az aks get-credentials -g <rg> -n aks-pagos-prod-brs", "az aks nodepool list -g <rg> --cluster-name aks-pagos-prod-brs -o table", "az aks nodepool scale -g <rg> --cluster-name <aks> -n nodepool1 --node-count 3", "az aks get-upgrades -g <rg> -n <aks> -o table", "az aks update -g <rg> -n <aks> --attach-acr acrpagosprod", "az aks stop -g <rg> -n aks-pagos-dev-brs"]],
    c_network: ["az network vnet", "Crear y consultar redes virtuales y subredes.", "Permite ver el direccionamiento de la red (para planear rangos sin solapes), crear subredes y revisar peerings y private endpoints. En entrevistas suelen preguntar por el diseño: rangos que no se solapen con la red local ni con otras VNets que vas a conectar.", ["az network vnet list -o table", "az network vnet create -g <rg> -n vnet-prod-brs-001 --address-prefixes 10.10.0.0/16 --subnet-name snet-app --subnet-prefixes 10.10.1.0/24", "az network vnet subnet list -g <rg> --vnet-name vnet-prod-brs-001 -o table", "az network vnet peering list -g <rg> --vnet-name vnet-prod-brs-001 -o table", "az network private-endpoint list -g <rg> -o table"]],
    c_nsg: ["az network nsg", "Reglas de firewall de red (NSG).", "Crea reglas permitir/denegar con prioridad (de 100 a 4096; el número menor se evalúa primero). Para diagnosticar, lo más útil es ver las reglas efectivas de una tarjeta de red, que combinan el NSG de la subred y el de la NIC.", ["az network nsg rule list -g <rg> --nsg-name nsg-snet-app-prod -o table", "az network nsg rule create -g <rg> --nsg-name nsg-snet-app-prod -n allow-https --priority 100 --direction Inbound --access Allow --protocol Tcp --destination-port-ranges 443", "az network nic list-effective-nsg -g <rg> -n <nic-de-la-vm>"]],
    c_netwatch: ["az network watcher", "Herramientas de diagnóstico de red.", "Network Watcher responde '¿por qué no llega el tráfico?': test-ip-flow dice si un NSG permite o bloquea un paquete concreto y qué regla lo decide; show-next-hop muestra por dónde sale el tráfico (útil con firewalls y rutas personalizadas); test-connectivity prueba la conexión de punta a punta.", ["az network watcher test-ip-flow -g <rg> --vm <vm> --direction Inbound --protocol TCP --local 10.10.1.4:22 --remote 203.0.113.5:50000", "az network watcher show-next-hop -g <rg> --vm <vm> --source-ip 10.10.1.4 --dest-ip 10.20.0.4", "az network watcher test-connectivity -g <rg> --source-resource <vm> --dest-address sql-pagos-prod-brs.database.windows.net --dest-port 1433"]],
    c_keyvault: ["az keyvault", "Secretos, llaves y certificados.", "Para leer o escribir secretos necesitas un rol de datos (Key Vault Secrets User o Secrets Officer con RBAC); ser Owner de la suscripción no alcanza. --query value -o tsv devuelve solo el valor, útil en scripts. Evita escribir secretos en la línea de comandos (quedan en el historial): usa --file. Los vaults borrados quedan en soft delete: se pueden recuperar y, mientras tanto, su nombre no se puede reutilizar.", ["az keyvault secret set --vault-name kv-pagos-prod-brs -n db-password --file secreto.txt", "az keyvault secret show --vault-name kv-pagos-prod-brs -n db-password --query value -o tsv", "az keyvault secret list --vault-name kv-pagos-prod-brs -o table", "az keyvault certificate list --vault-name kv-pagos-prod-brs --query \"[].{nombre:name, vence:attributes.expires}\" -o table", "az keyvault list-deleted -o table"]],
    c_role: ["az role assignment", "Dar y revisar permisos (RBAC).", "Una asignación une tres cosas: quién (usuario, grupo, service principal o managed identity), qué rol (Reader, Contributor, Key Vault Secrets User…) y dónde (scope: suscripción, grupo o recurso). Aplica mínimo privilegio: el scope más pequeño y el rol más específico. Los cambios pueden tardar unos minutos en aplicarse.", ["az role assignment create --assignee <objectId-o-correo> --role \"Key Vault Secrets User\" --scope <id-del-key-vault>", "az role assignment list --assignee <objectId> --all -o table", "az role definition list --name \"Contributor\" --query \"[].permissions[].actions\"", "az ad signed-in-user show --query id -o tsv   # tu objectId"]],
    c_identity: ["az identity / identity assign", "Crear managed identities y asignarlas a recursos.", "Una identidad system-assigned se activa en el recurso y muere con él; una user-assigned es un recurso propio que puedes reutilizar. Después de asignarla, le das roles con az role assignment usando su principalId.", ["az webapp identity assign -g <rg> -n app-pagos-api-prod-brs     # system-assigned", "az webapp identity show -g <rg> -n app-pagos-api-prod-brs --query principalId -o tsv", "az identity create -g <rg> -n id-app-pagos-prod                # user-assigned", "az vm identity assign -g <rg> -n <vm> --identities id-app-pagos-prod"]],
    c_servicebus: ["az servicebus", "Revisar namespaces, colas y topics de Service Bus.", "Lo más usado en operación es ver cuántos mensajes hay activos y en dead-letter para saber si los consumidores están al día. Para leer o reenviar mensajes concretos se usa el Service Bus Explorer del portal o un script con el SDK.", ["az servicebus namespace list -o table", "az servicebus queue list -g <rg> --namespace-name sbns-pagos-prod-brs -o table", "az servicebus queue show -g <rg> --namespace-name sbns-pagos-prod-brs -n ordenes --query countDetails", "az servicebus topic subscription list -g <rg> --namespace-name <ns> --topic-name pagos -o table"]],
    c_apim: ["az apim", "Consultar y administrar API Management.", "Permite listar instancias, APIs y named values, e importar APIs desde una especificación OpenAPI. Eso facilita versionar la configuración de APIM como código y aplicarla desde un pipeline.", ["az apim list -o table", "az apim api list -g <rg> -n apim-pagos-prod-brs -o table", "az apim api import -g <rg> -n apim-pagos-prod-brs --api-id pagos --path pagos --specification-format OpenApi --specification-path openapi.yaml", "az apim nv list -g <rg> -n apim-pagos-prod-brs -o table"]],
    c_activity: ["az monitor activity-log", "Quién hizo qué cambio en Azure y cuándo.", "El Activity Log registra las operaciones sobre los recursos (crear, modificar, borrar, reiniciar) con el usuario o la identidad que las hizo. Es lo primero a revisar cuando algo 'cambió solo'. Se conserva 90 días; para más tiempo se envía a Log Analytics.", ["az monitor activity-log list -g <rg> --offset 24h -o table", "az monitor activity-log list -g <rg> --offset 7d --query \"[?operationName.value=='Microsoft.Web/sites/restart/action'].{quien:caller, cuando:eventTimestamp}\" -o table"]],
    c_metrics: ["az monitor metrics", "Consultar métricas y alertas.", "Lee métricas de cualquier recurso (CPU, peticiones, errores 5xx, mensajes en cola) para un periodo y una agregación. También lista y crea alertas de métricas.", ["az monitor metrics list --resource <id-de-la-app> --metric Http5xx --interval PT5M --aggregation Total -o table", "az monitor metrics list-definitions --resource <id> -o table   # qué métricas existen", "az monitor metrics alert list -g <rg> -o table"]],
    c_logs: ["az monitor log-analytics query", "Ejecutar consultas KQL desde la terminal.", "Consulta un workspace de Log Analytics (se identifica por su customer ID, un GUID) con KQL. Útil para scripts de diagnóstico o reportes automáticos.", ["az monitor log-analytics workspace show -g <rg> -n log-prod-brs-001 --query customerId -o tsv", "az monitor log-analytics query -w <workspace-guid> --analytics-query \"AppRequests | where Success == false | summarize count() by ResultCode\" -o table"]],
    c_deployment: ["az deployment", "Desplegar infraestructura como código (Bicep / ARM).", "Despliega una plantilla Bicep o ARM en un grupo de recursos (también a nivel de suscripción, management group o tenant). what-if muestra qué se creará, cambiará o borrará antes de aplicar: es el equivalente a terraform plan. El modo Incremental (por defecto) no toca lo que no está en la plantilla.", ["az deployment group what-if -g <rg> --template-file main.bicep --parameters @params.prod.json", "az deployment group create -g <rg> --template-file main.bicep --parameters @params.prod.json", "az deployment group list -g <rg> -o table", "az bicep build --file main.bicep"], "--mode Complete borra del grupo todos los recursos que no estén en la plantilla."],
    c_acr: ["az acr", "Administrar Azure Container Registry.", "login autentica tu Docker local contra el registry con tu identidad de Azure. build construye la imagen en la nube (ACR Tasks), sin Docker local. Con repository ves qué imágenes y tags hay.", ["az acr login -n acrpagosprod", "az acr build -r acrpagosprod -t pagos-api:1.4.0 .", "az acr repository list -n acrpagosprod -o table", "az acr repository show-tags -n acrpagosprod --repository pagos-api -o table"]],
    c_help: ["az find / --help / extensiones", "Encontrar el comando correcto y su sintaxis.", "az find busca ejemplos de uso, --help muestra todos los parámetros de cualquier comando y az interactive abre una terminal con autocompletado. Algunos servicios necesitan extensiones (az extension add); az upgrade actualiza la CLI.", ["az find \"az webapp deployment slot\"", "az webapp deployment slot swap --help", "az interactive", "az extension add --name application-insights", "az upgrade"]],

    s_appservice: ["App Service responde 502 / 503", "La aplicación no contesta o devuelve error justo después de un despliegue o un cambio.", "Causas típicas: la app no arranca (excepción al iniciar, dependencia que falta), escucha en un puerto distinto al esperado (en contenedores, WEBSITES_PORT), una referencia a Key Vault o una connection string rota, el plan saturado de CPU o memoria, o una petición que supera el tiempo máximo de respuesta (unos 230 segundos). Cómo resolverlo: 1) contén primero: si desplegaste en un slot, haz swap de vuelta; 2) revisa el log stream y la consola Kudu; 3) compara los App Settings con la versión anterior; 4) revisa CPU y memoria del plan y escala si hace falta; 5) mira las dependencias que fallan en Application Insights.", ["az webapp deployment slot swap -g <rg> -n <app> --slot staging --target-slot production   # rollback", "az webapp log tail -g <rg> -n <app>", "az webapp config appsettings list -g <rg> -n <app> -o table", "az monitor metrics list --resource <id-del-plan> --metric CpuPercentage MemoryPercentage --interval PT5M -o table"]],
    s_kvref: ["Referencia a Key Vault no resuelve", "El App Setting muestra el texto @Microsoft.KeyVault(...) en lugar del valor, o la app falla por falta de un secreto.", "Causas: la app no tiene managed identity habilitada; la identidad no tiene permiso de leer secretos (rol Key Vault Secrets User o access policy); el Key Vault tiene firewall o private endpoint y la app no sale por la VNet (requiere VNet Integration); el nombre o la versión del secreto están mal escritos, o el secreto está deshabilitado o vencido. Si usas una identidad user-assigned, hay que indicarla en la propiedad keyVaultReferenceIdentity. Cómo resolverlo: en el portal, la configuración de la app muestra el estado de cada referencia (Resolved o el error); revisa identidad, rol y red en ese orden.", ["az webapp identity show -g <rg> -n <app> --query principalId -o tsv", "az role assignment list --assignee <principalId> --all -o table", "az keyvault secret show --vault-name kv-pagos-prod-brs -n db-password --query attributes", "az webapp config appsettings list -g <rg> -n <app> --query \"[?contains(value,'KeyVault')]\""]],
    s_cert: ["Certificado SSL vencido o inválido", "Los clientes reciben errores de certificado o una integración entre servicios falla por TLS.", "Causas: el certificado venció; se renovó en Key Vault pero el servicio (App Service, Application Gateway, APIM) sigue usando la versión anterior; o la cadena está incompleta (falta el certificado intermedio). Cómo resolverlo: renueva o carga el certificado y vuelve a asociarlo al binding; verifica la cadena y la fecha desde afuera. Prevención: certificados en Key Vault con renovación automática, servicios que referencien el secreto sin versión (toman la última) e inventario con alertas 30 días antes del vencimiento.", ["openssl s_client -connect pagos.contoso.com:443 -servername pagos.contoso.com < /dev/null | openssl x509 -noout -dates -issuer", "az keyvault certificate list --vault-name <kv> --query \"[].{nombre:name, vence:attributes.expires}\" -o table", "az webapp config ssl list -g <rg> -o table"]],
    s_authz: ["AuthorizationFailed (403)", "\"The client ... does not have authorization to perform action ... over scope ...\".", "Te falta un rol RBAC para esa acción en ese scope. Causas: no tienes el rol, lo tienes en otro scope (otro grupo o suscripción), estás en la suscripción equivocada, la asignación es reciente y aún no se propaga (unos minutos), o tu rol es elegible en PIM y no lo has activado. Recuerda que los permisos de datos (leer secretos, blobs o mensajes) son roles distintos a los de administración: ser Owner no da acceso a los secretos de un Key Vault con RBAC. Cómo resolverlo: el mensaje dice exactamente la acción y el scope; compáralo con tus asignaciones y pide el rol mínimo necesario.", ["az account show --query \"{suscripcion:name, usuario:user.name}\"", "az ad signed-in-user show --query id -o tsv", "az role assignment list --assignee <objectId> --all -o table"]],
    s_policy: ["RequestDisallowedByPolicy", "Azure rechaza la creación o el cambio porque viola una Azure Policy.", "Una política asignada (en el management group, la suscripción o el grupo) prohíbe lo que intentas: región no permitida, SKU no autorizado, falta de etiquetas obligatorias, recurso con acceso público, etc. El error incluye el nombre de la asignación y de la definición que lo bloqueó. Cómo resolverlo: ajusta el recurso para cumplir la política (región, SKU, tags, red privada). Si es un caso justificado, se solicita una exención (policy exemption) al equipo de gobierno; la política no se desactiva.", ["az policy assignment list --disable-scope-strict-match -o table", "az policy assignment show -n <nombre-de-la-asignacion>", "az policy state list -g <rg> --filter \"complianceState eq 'NonCompliant'\" -o table"]],
    s_lock: ["ScopeLocked", "No puedes borrar o modificar un recurso aunque tengas permisos.", "Hay un lock en el recurso, en su grupo o en la suscripción (se heredan). CanNotDelete impide borrar; ReadOnly impide cualquier cambio y además bloquea algunas operaciones que parecen de lectura (listar las llaves de un Storage Account, ciertas configuraciones de App Service). Cómo resolverlo: identifica el lock y su nivel; si el cambio está aprobado, quítalo, haz el cambio y vuelve a ponerlo. Los locks suelen proteger producción a propósito: confirma antes de quitarlos.", ["az lock list -g <rg> -o table", "az lock list --resource <id-del-recurso> -o table", "az lock delete -n <nombre-del-lock> -g <rg>"]],
    s_pe: ["No conecta por Private Endpoint", "La app no llega a SQL, Storage o Key Vault desde que se usa private endpoint (timeout o acceso denegado).", "La gran mayoría de las veces es DNS: el nombre del servicio sigue resolviendo a la IP pública (bloqueada) en lugar de la privada. Causas: la Private DNS Zone (por ejemplo privatelink.database.windows.net) no existe, no está enlazada a la VNet desde donde se consulta, o el DNS personalizado de la VNet no reenvía a Azure DNS (168.63.129.16). Otras: la app no tiene VNet Integration (sale por internet), o un NSG o firewall bloquea el puerto. Cómo resolverlo: resuelve el nombre desde donde corre la app y verifica que devuelva una IP privada.", ["nslookup sql-pagos-prod-brs.database.windows.net   # desde la VM o la consola Kudu", "az network private-dns zone list -o table", "az network private-dns link vnet list -g <rg> -z privatelink.database.windows.net -o table", "az network private-endpoint show -g <rg> -n pep-sql-pagos-prod --query customDnsConfigs"]],
    s_vm: ["VM sin acceso por SSH o RDP", "No logras conectarte a una máquina virtual.", "Revisa en orden: 1) ¿está encendida? (deallocated no responde); 2) ¿la red lo permite? NSG de la subred y de la NIC (reglas efectivas), firewall o rutas; 3) ¿tiene IP pública o debes entrar por Bastion o VPN?; 4) ¿el sistema arrancó? Boot diagnostics y la consola serie muestran errores de arranque, disco lleno o fstab mal configurado; 5) ¿las credenciales o el servicio SSH están bien? Con run-command ejecutas comandos dentro de la VM sin red, por ejemplo para reiniciar sshd o revisar el disco.", ["az vm get-instance-view -g <rg> -n <vm> --query \"instanceView.statuses[].displayStatus\"", "az network nic list-effective-nsg -g <rg> -n <nic>", "az network watcher test-ip-flow -g <rg> --vm <vm> --direction Inbound --protocol TCP --local <ip-privada>:22 --remote <tu-ip>:50000", "az vm boot-diagnostics get-boot-log -g <rg> -n <vm>", "az vm run-command invoke -g <rg> -n <vm> --command-id RunShellScript --scripts \"systemctl status sshd; df -h\""]],
    s_deploy: ["DeploymentFailed (Bicep / ARM)", "El despliegue de la plantilla falla, total o parcialmente.", "El error general no dice mucho: el detalle está en las operaciones del despliegue. Causas frecuentes: nombre ya usado (Storage Account y Key Vault deben ser únicos en todo Azure; un Key Vault borrado sigue reservando el nombre por el soft delete), parámetros inválidos, dependencias en mal orden, cuota o SKU no disponible, Azure Policy o falta de permisos. Cómo resolverlo: lee el error de la operación fallida, corrige y vuelve a desplegar (los despliegues son idempotentes). Usa what-if antes de aplicar.", ["az deployment group show -g <rg> -n <despliegue> --query properties.error", "az deployment operation group list -g <rg> -n <despliegue> --query \"[?properties.provisioningState=='Failed'].properties.statusMessage\"", "az keyvault list-deleted -o table", "az keyvault recover -n kv-pagos-prod-brs     # o purge si de verdad se quiere eliminar"]],
    s_quota: ["QuotaExceeded / SKU no disponible", "No puedes crear una VM, un nodo de AKS o un plan porque no hay cupo o capacidad.", "Son dos problemas distintos. La cuota (límite de vCPU por familia de VM y región en tu suscripción) se aumenta con una solicitud desde el portal de cuotas o soporte. La capacidad (SkuNotAvailable, AllocationFailed) significa que ese tamaño no está disponible en esa región o zona en ese momento. Cómo resolverlo: revisa el uso contra el límite, pide aumento de cuota con anticipación (antes de un go-live) o usa otro tamaño, otra zona u otra región.", ["az vm list-usage -l brazilsouth -o table", "az vm list-skus -l brazilsouth --size Standard_D4 --query \"[].{sku:name, zonas:locationInfo[0].zones, restriccion:restrictions[0].reasonCode}\" -o table"]],
    s_dlq: ["Mensajes en dead-letter (Service Bus)", "Crece el conteo de mensajes en la dead-letter queue de una cola o suscripción.", "Un mensaje va a dead-letter cuando supera el número máximo de entregas (MaxDeliveryCount, por defecto 10: el consumidor falló 10 veces), cuando expira su TTL (si está activado el dead-lettering por expiración) o cuando la aplicación lo envía explícitamente. Cada mensaje trae DeadLetterReason y DeadLetterErrorDescription. Cómo resolverlo: revisa el motivo en el Service Bus Explorer, corrige la causa (dato inválido, dependencia caída, error del consumidor) y reprocesa los mensajes de forma controlada. Prevención: alerta sobre la métrica DeadletteredMessages.", ["az servicebus queue show -g <rg> --namespace-name sbns-pagos-prod-brs -n ordenes --query countDetails", "az monitor metrics list --resource <id-del-namespace> --metric DeadletteredMessages --interval PT5M -o table"]],

    f_g: ["-g / --resource-group", "El grupo de recursos donde está (o estará) el recurso.", "Casi todos los comandos lo piden junto con -n. Si trabajas mucho en un mismo grupo, puedes dejarlo por defecto con az config set defaults.group.", ["az webapp show -g rg-pagos-prod-brs-001 -n app-pagos-api-prod-brs", "az config set defaults.group=rg-pagos-prod-brs-001"]],
    f_n: ["-n / --name", "El nombre del recurso.", "Identifica el recurso dentro del grupo. En algunos comandos -n se refiere a un recurso hijo según el contexto (en az servicebus queue, -n es la cola y el namespace va en --namespace-name): revisa --help si dudas.", ["az vm show -g <rg> -n vm-pagos-prod-brs-01", "az servicebus queue show -g <rg> --namespace-name sbns-pagos-prod-brs -n ordenes"]],
    f_ids: ["--ids", "Identifica recursos por su ID completo, en lugar de -g y -n.", "Acepta uno o varios IDs de recurso (/subscriptions/.../resourceGroups/.../providers/...). Muy útil para encadenar comandos: obtienes IDs con --query y los pasas a otro comando.", ["az vm deallocate --ids $(az vm list -g <rg> --query \"[].id\" -o tsv)", "az resource show --ids <id-del-recurso>"]],
    f_sub: ["--subscription", "Ejecuta el comando en otra suscripción sin cambiar la activa.", "Acepta nombre o ID. Evita cambiar el contexto global con az account set, lo que es más seguro en scripts que trabajan con varias suscripciones.", ["az group list --subscription sub-pagos-dev -o table"]],
    f_l: ["-l / --location", "La región donde se crea el recurso.", "Usa el nombre corto (brazilsouth, eastus2). Si no lo indicas, muchos comandos toman la región del grupo de recursos.", ["az group create -n rg-pagos-dev-brs-001 -l brazilsouth", "az account list-locations --query \"[].name\" -o tsv"]],
    f_o: ["-o / --output", "El formato de la respuesta.", "json (por defecto) para ver todo; table para leer en pantalla; tsv para scripts (sin comillas ni encabezados, ideal para guardar en variables); yaml; jsonc (json con colores); none para no mostrar nada.", ["az vm list -o table", "ID=$(az group show -n rg-pagos-prod-brs-001 --query id -o tsv)", "az webapp list -o yaml"]],
    f_query: ["--query", "Filtra y da forma al resultado con JMESPath.", "Se ejecuta en tu equipo sobre la respuesta: eliges campos, filtras con condiciones y renombras columnas. Combinado con -o table o -o tsv evita depender de jq o de grep. Sintaxis: [] recorre listas, [?condición] filtra y {alias:campo} arma columnas.", ["az vm list -d --query \"[?powerState=='VM running'].name\" -o tsv", "az resource list -g <rg> --query \"[].{nombre:name, tipo:type, region:location}\" -o table", "az webapp show -g <rg> -n <app> --query \"siteConfig.alwaysOn\""]],
    f_yes: ["-y / --yes", "Confirma automáticamente, sin preguntar.", "Necesario en scripts y pipelines para comandos que piden confirmación (borrar grupos, recursos o locks).", ["az group delete -n rg-pagos-dev-brs-001 --yes"], "Con --yes no hay segunda oportunidad: revisa la suscripción y el nombre antes."],
    f_nowait: ["--no-wait", "No espera a que la operación termine.", "Devuelve el control de inmediato mientras Azure sigue trabajando (útil para operaciones largas como borrar un grupo o crear un clúster). Para esperar después se usa el comando wait del servicio.", ["az group delete -n rg-pagos-dev-brs-001 --yes --no-wait", "az aks start -g <rg> -n aks-pagos-dev-brs --no-wait", "az group wait -n rg-pagos-dev-brs-001 --deleted"]],
    f_debug: ["--debug / --verbose", "Muestra el detalle de lo que hace la CLI.", "--verbose agrega información de progreso; --debug muestra cada petición HTTP a la API de Azure y su respuesta, ideal para entender errores raros o reportar un problema.", ["az webapp show -g <rg> -n <app> --verbose", "az vm list --debug 2> debug.log"]],
    f_only: ["--only-show-errors", "Oculta las advertencias y muestra solo errores.", "Útil en pipelines y scripts para que los avisos (comandos en preview, cambios futuros) no ensucien la salida ni rompan el procesamiento.", ["az extension add --name aks-preview --only-show-errors"]],
    f_defaults: ["az config set defaults", "Guarda valores por defecto para no repetirlos.", "Puedes fijar grupo, región u otros parámetros por defecto en tu configuración local. Úsalo con cuidado: un valor por defecto olvidado puede hacer que un comando actúe sobre el grupo equivocado.", ["az config set defaults.group=rg-pagos-dev-brs-001 defaults.location=brazilsouth", "az config get defaults", "az config unset defaults.group"]],
    f_help: ["-h / --help", "Ayuda de cualquier grupo o comando.", "Muestra subcomandos, parámetros obligatorios y opcionales, y ejemplos. Funciona en cualquier nivel: az -h, az webapp -h, az webapp deployment slot swap -h.", ["az webapp -h", "az keyvault secret set --help"]],
  },
};

export default guia;
